import { Schema } from "effect"

/**
 * One identifier format for the whole system: UUIDv7, generated by Postgres.
 * The same value is used in the database, RPC, CLI and URLs. Entity types are
 * separated by brands, not by string prefixes.
 *
 * Vendors (hh, Telegram, RFC Message-ID) are *not* identifiers in this sense.
 * They live in `external_id` next to `source`.
 */
export const UuidV7 = Schema.String.pipe(Schema.check(Schema.isUUID(7)))

export type UuidV7 = typeof UuidV7.Type

export const UserId = Schema.String.pipe(Schema.brand("UserId"))
export const HhAccountId = UuidV7.pipe(Schema.brand("HhAccountId"))
export const ResumeId = UuidV7.pipe(Schema.brand("ResumeId"))
export const EmployerId = UuidV7.pipe(Schema.brand("EmployerId"))
export const VacancyId = UuidV7.pipe(Schema.brand("VacancyId"))
export const KeywordId = UuidV7.pipe(Schema.brand("KeywordId"))
export const KeywordAliasId = UuidV7.pipe(Schema.brand("KeywordAliasId"))
export const PresetId = UuidV7.pipe(Schema.brand("PresetId"))
export const DecisionId = UuidV7.pipe(Schema.brand("DecisionId"))
export const ApplicationId = UuidV7.pipe(Schema.brand("ApplicationId"))
export const KitId = UuidV7.pipe(Schema.brand("KitId"))
export const AttemptId = UuidV7.pipe(Schema.brand("AttemptId"))
export const HarnessId = UuidV7.pipe(Schema.brand("HarnessId"))
export const HarnessJobId = UuidV7.pipe(Schema.brand("HarnessJobId"))
export const LeaseId = UuidV7.pipe(Schema.brand("LeaseId"))
export const ScheduleId = UuidV7.pipe(Schema.brand("ScheduleId"))

export type UserId = typeof UserId.Type
export type HhAccountId = typeof HhAccountId.Type
export type ResumeId = typeof ResumeId.Type
export type EmployerId = typeof EmployerId.Type
export type VacancyId = typeof VacancyId.Type
export type KeywordId = typeof KeywordId.Type
export type KeywordAliasId = typeof KeywordAliasId.Type
export type PresetId = typeof PresetId.Type
export type DecisionId = typeof DecisionId.Type
export type ApplicationId = typeof ApplicationId.Type
export type KitId = typeof KitId.Type
export type AttemptId = typeof AttemptId.Type
export type HarnessId = typeof HarnessId.Type
export type HarnessJobId = typeof HarnessJobId.Type
export type LeaseId = typeof LeaseId.Type
export type ScheduleId = typeof ScheduleId.Type

/** External ids stay strings: a vendor may reuse them or make them negative. */
export const HhVacancyId = Schema.String.pipe(Schema.brand("HhVacancyId"))
export const HhEmployerId = Schema.String.pipe(Schema.brand("HhEmployerId"))
export const HhResumeId = Schema.String.pipe(Schema.brand("HhResumeId"))

export type HhVacancyId = typeof HhVacancyId.Type
export type HhEmployerId = typeof HhEmployerId.Type
export type HhResumeId = typeof HhResumeId.Type
